import ast,json,hashlib,subprocess
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))

def check_schema(value,schema,path='"'$'"'):
 typ=schema.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
 if typ in types: assert isinstance(value,types[typ]),(path,typ)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,dict):
  for k in schema.get('required',[]): assert k in value,(path,k)
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),path
  for k,v in value.items():
   if k in schema.get('properties',{}): check_schema(v,schema['properties'][k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value): check_schema(v,schema.get('items',{}),path+str(i))
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
check_schema(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial']==r['context']['incumbent']
assert len(p['variants'])==4 and len(set(v['name'] for v in p['variants']))==4
old=ast.parse(Path('candidate.py').read_text());oldclass=next(n for n in old.body if isinstance(n,ast.ClassDef));oldmethods={n.name:n for n in oldclass.body if isinstance(n,ast.FunctionDef)}
classes=[]
for v in p['variants']:
 text=Path(v['file']).read_text();compile(text,v['file'],'exec');tree=ast.parse(text)
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config']
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef));classes.append(ast.dump(cls,include_attributes=False));methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 newinit=methods['__init__'];oldinit=oldmethods['__init__']
 assert ast.dump(ast.Module(body=newinit.body[:len(oldinit.body)],type_ignores=[]))==ast.dump(ast.Module(body=oldinit.body,type_ignores=[]))
 for name,method in oldmethods.items():
  if name=='__init__': continue
  newname={'forward':'_exchangeable_forward','diagnostics':'_exchangeable_diagnostics'}.get(name,name)
  newmethod=methods[newname]
  assert ast.dump(ast.Module(body=method.body,type_ignores=[]))==ast.dump(ast.Module(body=newmethod.body,type_ignores=[])),(v['file'],name)
 clone=methods['_parent_forward_with_context']
 assert ast.dump(ast.Module(body=clone.body[:-3],type_ignores=[]))==ast.dump(ast.Module(body=oldmethods['_parent_forward'].body[:-1],type_ignores=[]))
 # Deliberately conservative top-level source-boundary check.
 for n in tree.body:
  assert isinstance(n,(ast.Expr,ast.Import,ast.ImportFrom,ast.Assign,ast.ClassDef))
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(x.name in ('math','torch') for x in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module=='torch' and all(x.name=='nn' for x in n.names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in ('open','eval','exec','__import__','compile','input')
 assert 'training_loss' not in methods and 'make_optimizer' not in text
 # Diagnostic dictionary key count, including update/witness defaults.
 diag=methods['diagnostics']; keys=[]
 for n in ast.walk(diag):
  if isinstance(n,ast.Dict):
   keys.extend(k.value for k in n.keys if isinstance(k,ast.Constant) and isinstance(k.value,str) and (k.value not in ('static','history_category','history_brand','history_type','history_age_seconds','history_mask')))
 assert len(set(keys))+1<=64
 print(v['file'],'syntax/source/inheritance checks PASS; diagnostic keys',len(set(keys))+1,'sha256',hashlib.sha256(text.encode()).hexdigest())
assert len(set(classes))==1
assert hashlib.sha256(Path('candidate.py').read_bytes()).hexdigest()=='ef9e0512a7640a8b3e06b848ad191f38dde91b40c97bcbec8275e49d902334c1'
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
print('Study schema, allowed evidence, protocol/config, four identical Model ASTs, exact parent constructor prefix and',len(oldmethods)-1,'inherited methods PASS.')
print('Budget remaining',r['context']['remaining_seconds'],'16 capped calls',16*r['context']['protocol']['trial_cap_seconds'])
PY"

